package io.beep.core.adapter.out.postgres;
import static org.assertj.core.api.Assertions.*;
import io.beep.core.app.port.EcosystemRepository.*;
import io.beep.core.app.conversion.DeveloperUseCase.EventCommand;
import io.beep.core.domain.user.*;
import io.beep.core.domain.workspace.Workspace;
import io.beep.core.domain.team.WorkspaceRole;
import java.time.*;
import java.util.*;
import org.flywaydb.core.Flyway;
import org.jooq.DSLContext;
import org.jooq.SQLDialect;
import org.jooq.impl.DSL;
import org.junit.jupiter.api.*;
import org.postgresql.ds.PGSimpleDataSource;
import org.testcontainers.containers.PostgreSQLContainer;
class EcosystemIT {
  static DSLContext db;static final Instant NOW=Instant.parse("2026-10-25T12:00:00Z");PostgresEcosystemAdapter data;User owner,member;Workspace ws;
  @BeforeAll static void setup(){var pg=new PGSimpleDataSource();String url=System.getenv("TEST_DATABASE_URL");if(url==null||url.isBlank()){var c=new PostgreSQLContainer<>("postgres:16-alpine");c.start();url=c.getJdbcUrl();pg.setUser(c.getUsername());pg.setPassword(c.getPassword());}pg.setUrl(url);var f=Flyway.configure().dataSource(pg).cleanDisabled(false).load();f.clean();f.migrate();f.validate();db=DSL.using(pg,SQLDialect.POSTGRES);}
  User user(String email){var u=User.register(UUID.randomUUID(),new Email(email),"hash","fr",NOW).verifyEmail(NOW);new PostgresUserAdapter(db).insert(u);return u;}
  @BeforeEach void init(){db.execute("TRUNCATE users,slugs CASCADE");owner=user("owner@example.org");member=user("member@example.org");ws=new PostgresWorkspaceAdapter(db).ensure(Workspace.personal(UUID.randomUUID(),owner.id(),"Team",NOW));db.execute("UPDATE workspaces SET plan_code='elite' WHERE id=?",ws.id());data=new PostgresEcosystemAdapter(db);}
  @Test void multipleOwnedWorkspacesKeepOneStablePersonalWorkspace(){UUID second=db.transactionResult(c->new PostgresEcosystemAdapter(c.dsl()).createWorkspace(owner.id(),"Second",NOW));assertThat(second).isNotEqualTo(ws.id());assertThat(new PostgresWorkspaceAdapter(db).findByOwner(owner.id()).orElseThrow().id()).isEqualTo(ws.id());assertThat(data.workspaces(owner.id())).hasSize(2);assertThat(data.role(second,member.id())).isEmpty();}
  @Test void invitationIsConsumedOnceAndMembershipIsImmediatelyRevocable(){var i=new Invite(UUID.randomUUID(),ws.id(),member.email().value(),"viewer","hash",NOW.plusSeconds(604800));db.transaction(c->{var d=new PostgresEcosystemAdapter(c.dsl());d.invite(i);d.accept(i,member.id(),NOW);});assertThat(data.invitation("hash",NOW)).isEmpty();assertThat(data.role(ws.id(),member.id())).contains(WorkspaceRole.VIEWER);data.remove(ws.id(),member.id());assertThat(data.role(ws.id(),member.id())).isEmpty();assertThat(data.team(ws.id()).get("activeSeats")).isEqualTo(1L);}
  @Test void labelsCannotBeAttachedAcrossWorkspaces(){UUID other=db.transactionResult(c->new PostgresEcosystemAdapter(c.dsl()).createWorkspace(member.id(),"Other",NOW));UUID label=data.label(other,"tag","Private");UUID link=UUID.randomUUID();db.execute("INSERT INTO links(id,workspace_id,slug,destination,created_at,updated_at) VALUES(?,?,'example','https://example.org',now(),now())",link,ws.id());assertThatThrownBy(()->data.organize(ws.id(),link,null,List.of(label))).hasMessage("not_found");}
  Integration integration(){var i=new Integration(UUID.randomUUID(),ws.id(),"stripe","Stripe",Map.of(),"cipher",null,"active");data.integration(i);return i;}
  @Test void commerceDeliveriesAreDeduplicatedAndLeased(){var i=integration();EventCommand command=new EventCommand(UUID.randomUUID(),"sale",null,null,new java.math.BigDecimal("10"),"EUR",null,true,Map.of());var e=new Incoming(command.eventId(),i.id(),ws.id(),"sale:pi_1","sale",command,"pending",0,NOW);assertThat(data.incoming(e)).isTrue();assertThat(data.incoming(e)).isFalse();var first=db.transactionResult(c->new PostgresEcosystemAdapter(c.dsl()).claimIncoming(NOW.plusSeconds(1),10));assertThat(first).hasSize(1);assertThat(data.claimIncoming(NOW.plusSeconds(2),10)).isEmpty();data.incomingResult(e.id(),first.getFirst().attempts(),null,NOW.plusSeconds(3));assertThat(data.staffWorkspace(ws.id()).get("events").toString()).contains("processed");}
  @Test void disablingIntegrationCancelsPendingEventsAndErasesCredentials(){var i=integration();var cmd=new EventCommand(UUID.randomUUID(),"sale",null,null,java.math.BigDecimal.ONE,"EUR",null,true,Map.of());data.incoming(new Incoming(cmd.eventId(),i.id(),ws.id(),"sale:1","sale",cmd,"pending",0,NOW));data.disconnect(ws.id(),i.id());assertThat(data.integration(i.id()).orElseThrow().credentials()).isEmpty();assertThat(data.claimIncoming(NOW.plusSeconds(1),10)).isEmpty();}
  @Test void reportsAreScheduledOnceAndOwnerMailDoesNotStoreAnAddress(){data.report(ws.id(),"daily",true,NOW);db.transaction(c->{new PostgresEcosystemAdapter(c.dsl()).scheduleReports(NOW.plusSeconds(86401));});db.transaction(c->{new PostgresEcosystemAdapter(c.dsl()).scheduleReports(NOW.plusSeconds(86402));});assertThat(db.fetchValue("SELECT count(*) FROM ecosystem_tasks")).isEqualTo(1L);assertThat(db.fetchValue("SELECT destination_cipher FROM ecosystem_tasks")).isEqualTo("owner");}
  @Test void dailyReportsUseTheSameCompleteUtcDayForClicksAndSales(){for(int days=0;days<3;days++){Instant stamp=NOW.minus(Duration.ofDays(days));db.execute("INSERT INTO rollups_daily VALUES('link',?,?,?::date,'total','',?,1)",UUID.randomUUID(),ws.id(),stamp.atOffset(ZoneOffset.UTC).toLocalDate(),30-days*10);db.execute("INSERT INTO conversion_events(id,workspace_id,name,value,currency,at) VALUES(?,?,'sale',1,'EUR',?::timestamptz)",UUID.randomUUID(),ws.id(),stamp.atOffset(ZoneOffset.UTC));}data.report(ws.id(),"daily",true,NOW.minus(Duration.ofDays(2)));db.transaction(c->new PostgresEcosystemAdapter(c.dsl()).scheduleReports(NOW));assertThat((String)db.fetchValue("SELECT body FROM ecosystem_tasks")).contains("clicks=20 · sales=1");}
  @Test void contentRejectsStalePublications(){var p=new HashMap<String,Object>(Map.of("kind","blog","slug","hello","locale","fr","title","Hello","body","Text","status","published","version",1));data.publish(UUID.randomUUID(),p,NOW);assertThatThrownBy(()->data.publish(UUID.randomUUID(),p,NOW)).hasMessage("conflict");p.put("version",2);p.put("status","withdrawn");data.publish(UUID.randomUUID(),p,NOW);assertThat(data.content().toString()).contains("withdrawn");}
  @Test void workspaceAuditIsImmutableButAccountErasureCascades(){data.audit(ws.id(),owner.id(),"test","id",NOW);assertThatThrownBy(()->db.execute("UPDATE workspace_audit SET action='fake'")).hasMessageContaining("append only");new PostgresPrivacyAdapter(db).erase(owner.id());assertThat(db.fetchValue("SELECT count(*) FROM workspace_audit")).isEqualTo(0L);}
  @Test void visitorErasureCancelsClaimedCommerceWorkWithoutLosingDeduplication(){var i=integration();String visitor="a".repeat(64);var cmd=new EventCommand(UUID.randomUUID(),"sale",visitor,null,java.math.BigDecimal.ONE,"EUR",null,true,Map.of());var e=new Incoming(cmd.eventId(),i.id(),ws.id(),"sale:private","sale",cmd,"pending",0,NOW);data.incoming(e);var claimed=data.claimIncoming(NOW.plusSeconds(1),10).getFirst();var developer=new PostgresDeveloperAdapter(db);assertThat(developer.visitor(ws.id(),visitor)).hasSize(1);db.transaction(c->new PostgresDeveloperAdapter(c.dsl()).eraseVisitor(ws.id(),visitor));assertThat(data.incomingActive(ws.id(),e.id(),claimed.attempts())).isFalse();assertThat(developer.visitor(ws.id(),visitor)).isEmpty();assertThat(data.incoming(e)).isFalse();assertThat(db.fetchValue("SELECT payload::text FROM integration_events WHERE id=?",e.id())).isEqualTo("{}");}
  UUID payment(String provider,String status,Instant paid){UUID id=UUID.randomUUID();db.execute("INSERT INTO payments(id,workspace_id,plan_code,billing_cycle,method,provider,provider_ref,status,list_price_xaf,amount_xaf,country,created_at,paid_at) VALUES(?,?,'elite','monthly','manual',?,?,?,10000,10000,'CM',?::timestamptz,?::timestamptz)",id,ws.id(),provider,id.toString(),status,NOW.atOffset(ZoneOffset.UTC),paid.atOffset(ZoneOffset.UTC));return id;}
  @Test void affiliateCommissionsExcludeSandboxAndRespectCoolingOffAndPayoutIdempotency(){String code=data.joinAffiliate(member.id(),NOW);data.referral(owner.id(),ws.id(),code,NOW);payment("sandbox","succeeded",NOW.plusSeconds(1));payment("manual","succeeded",NOW.plusSeconds(2));db.transaction(c->new PostgresEcosystemAdapter(c.dsl()).accrueCommissions(NOW.plusSeconds(10)));assertThat(db.fetchValue("SELECT count(*) FROM affiliate_commissions")).isEqualTo(1L);assertThat(db.fetchValue("SELECT status FROM affiliate_commissions")).isEqualTo("pending");Instant later=NOW.plus(Duration.ofDays(31));db.transaction(c->new PostgresEcosystemAdapter(c.dsl()).accrueCommissions(later));var commission=db.fetchOne("SELECT id,amount_xaf,status FROM affiliate_commissions");assertThat(commission.get("amount_xaf",Long.class)).isEqualTo(2000L);assertThat(commission.get("status",String.class)).isEqualTo("approved");UUID id=commission.get("id",UUID.class);db.transaction(c->new PostgresEcosystemAdapter(c.dsl()).payout(UUID.randomUUID(),List.of(id),"bank-123",later));assertThatThrownBy(()->db.transaction(c->new PostgresEcosystemAdapter(c.dsl()).payout(UUID.randomUUID(),List.of(id),"bank-456",later))).hasMessageContaining("conflict");}
  @Test void refundedPaymentsVoidUnpaidCommissions(){String code=data.joinAffiliate(member.id(),NOW);data.referral(owner.id(),ws.id(),code,NOW);UUID id=payment("manual","succeeded",NOW.plusSeconds(1));data.accrueCommissions(NOW.plusSeconds(2));db.execute("UPDATE payments SET status='refunded' WHERE id=?",id);data.accrueCommissions(NOW.plusSeconds(3));assertThat(db.fetchValue("SELECT status FROM affiliate_commissions")).isEqualTo("void");}
  @Test void multipleWorkspacesDoNotInflateSignupActivationAndAreAllExported(){UUID other=db.transactionResult(c->new PostgresEcosystemAdapter(c.dsl()).createWorkspace(owner.id(),"Other",NOW));var activation=new PostgresPlatformMetricsAdapter(db).activation(NOW.minusSeconds(1),Duration.ofDays(7));assertThat(activation.signups()).isEqualTo(2L);var exported=new PostgresPrivacyAdapter(db).export(owner.id());assertThat((List<?>)exported.get("workspaces")).hasSize(2);new PostgresPrivacyAdapter(db).erase(owner.id());assertThat(db.fetchValue("SELECT count(*) FROM workspaces WHERE id=?",other)).isEqualTo(0L);}
  @Test void downgradedTeamKeepsOnlyItsAllowedSeatsAndOwnerCanStillManageEveryone(){var second=user("second@example.org");var third=user("third@example.org");int n=0;for(var u:List.of(member,second,third))db.execute("INSERT INTO workspace_members VALUES(?,?,'editor',?::timestamptz)",ws.id(),u.id(),NOW.plusSeconds(n++).atOffset(ZoneOffset.UTC));assertThat(data.canAccess(ws.id(),third.id())).isTrue();db.execute("UPDATE workspaces SET plan_code='pro' WHERE id=?",ws.id());assertThat(data.canAccess(ws.id(),member.id())).isTrue();assertThat(data.canAccess(ws.id(),second.id())).isTrue();assertThat(data.canAccess(ws.id(),third.id())).isFalse();assertThat(data.role(ws.id(),third.id())).contains(WorkspaceRole.EDITOR);db.execute("UPDATE workspaces SET plan_code='starter' WHERE id=?",ws.id());assertThat(data.canAccess(ws.id(),member.id())).isFalse();assertThat(data.canAccess(ws.id(),owner.id())).isTrue();}
  @Test void radarUsesTheSignedOutboxOncePerWindowAndRemovalCancelsDelivery(){UUID link=UUID.randomUUID(),endpoint=UUID.randomUUID();db.execute("INSERT INTO links(id,workspace_id,slug,destination,created_at,updated_at) VALUES(?,?,'health-check','https://example.org',now(),now())",link,ws.id());db.execute("INSERT INTO destination_health(link_id,checked_url,status,checked_at) VALUES(?,'https://example.org',500,?::timestamptz)",link,NOW.atOffset(ZoneOffset.UTC));new PostgresDeveloperAdapter(db).endpoint(new io.beep.core.app.port.DeveloperRepository.Endpoint(endpoint,ws.id(),"https://example.org/hook",Set.of("radar.alert"),"encrypted-secret",true,NOW));UUID rule=data.rule(ws.id(),"broken_link",1,"webhook","endpoint",link,endpoint,NOW);db.transaction(c->new PostgresEcosystemAdapter(c.dsl()).evaluateRadar(NOW));db.transaction(c->new PostgresEcosystemAdapter(c.dsl()).evaluateRadar(NOW.plusSeconds(61)));assertThat(db.fetchValue("SELECT count(*) FROM webhook_deliveries WHERE endpoint_id=?",endpoint)).isEqualTo(1L);assertThat(db.fetchValue("SELECT count(*) FROM ecosystem_tasks")).isEqualTo(0L);db.transaction(c->new PostgresEcosystemAdapter(c.dsl()).removeRule(ws.id(),rule));assertThat(db.fetchValue("SELECT enabled FROM webhook_endpoints WHERE id=?",endpoint)).isEqualTo(false);assertThat(db.fetchValue("SELECT status FROM webhook_deliveries WHERE endpoint_id=?",endpoint)).isEqualTo("cancelled");}
}
